with latest_match as (select s.id, s.country, s.city, s.rating, latest.product_brand from suppliers s left join lateral (select c.brand as product_brand from products c where c.supplier_id = s.id order by c.stock_qty desc, c.id desc limit 1) latest on true) select case when rating >= 4.2 then 'PREMIUM' else 'STANDARD' end as rating_tier, city, count(*) filter (where product_brand = 'Umbrella') as umbrella_rows, count_if(country = 'US') as us_events, count(*) as num_rows, count(*) as cnt from latest_match group by case when rating >= 4.2 then 'PREMIUM' else 'STANDARD' end, city having count(*) > 1 order by num_rows;
